+// Número de factura SSS-AAAA-NNNNNN (brain de empresa: estandares/documentos-fiscales.md).
+// Un valor fuera de rango es un error: nunca se trunca ni se ajusta.
+export function numeroFactura(sucursal, gestion, correlativo) {
+  const enRango = (v, min, max) => Number.isInteger(v) && v >= min && v <= max;
+  if (!enRango(sucursal, 1, 999)) throw new RangeError("Sucursal inválida: de 1 a 999");
+  if (!enRango(gestion, 1000, 9999)) throw new RangeError("Gestión inválida: 4 dígitos");
+  if (!enRango(correlativo, 1, 999999)) throw new RangeError("Correlativo inválido: de 1 a 999999");
+  return `${String(sucursal).padStart(3, "0")}-${gestion}-${String(correlativo).padStart(6, "0")}`;
+}
